/* Card set: Natural Wonders (generated from the approved roster-final.csv by the Natural Wonders build, schema per tools/csv-to-set.js).
   (natural-wonders.js exceeds the comfortable push size, so the remaining cards live in
   natural-wonders-additions.js, which must stay directly after 'natural-wonders.js' in sets/manifest.js.) */
CardSets.register({"id":"natural-wonders","name":"Natural Wonders","code":"WOND","description":"420 cards of Earth's great natural wonders — mountains and volcanoes, waterfalls, canyons, lakes, caves, forests, ice and reefs.","theme":{"primary":"#2f5d3a","secondary":"#c98a3d","artBackground":"#eef3e6","artFit":"cover"},"pack":{"name":"Natural Wonders Pack","emblem":"🏞️","skin":"natural-wonders"},"cards":[{"name":"Grand Canyon","rarity":"chase","id":"grand-canyon","subtitle":"Canyon","details":"Carved by the Colorado River in Arizona, this immense canyon runs 277 miles, up to 18 miles wide and over a mile deep, exposing ancient rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Canyon%20South%20Rim%20at%20Sunset.jpg?width=1024"},{"name":"Mount Everest","rarity":"chase","id":"mount-everest","subtitle":"Mountain","details":"Earth's highest mountain rises 8,849 metres above sea level on the Nepal-China border, its summit ridge shaped by wind, ice and extreme thin air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mt._Everest_from_Gokyo_Ri_November_5%2C_2012.jpg?width=1024"},{"name":"Great Barrier Reef","rarity":"chase","id":"great-barrier-reef","subtitle":"Reef","details":"The world's largest coral reef system stretches over 2,300 kilometres off Queensland, built by tiny polyps and visible as swirling turquoise shallows from space","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_View_of_Great_Barrier_Reef_%28Ank_Kumar%29_02.jpg?width=1024"},{"name":"Victoria Falls","rarity":"chase","id":"victoria-falls","subtitle":"Cataract","details":"The Zambezi River plunges over a basalt cliff more than a mile wide, dropping about 108 metres and raising a spray cloud visible for many kilometres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cataratas_Victoria%2C_Zambia-Zimbabue%2C_2018-07-27%2C_DD_04.jpg?width=800"},{"name":"Iguazu Falls","rarity":"chase","id":"iguazu-falls","subtitle":"Cataract","details":"A system of about 275 separate drops curves in a vast U shape along the Iguazu River, with the Devil's Throat carrying roughly half of the flow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/00_1826_Iguazu_Falls_-_South_America%2C_Brazil.jpg?width=1024"},{"name":"Niagara Falls","rarity":"chase","id":"niagara-falls","subtitle":"Cataract","details":"Three falls on the Niagara River drain Lake Erie toward Lake Ontario, and their combined flow makes this one of the great waterfalls by volume.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/3Falls_Niagara.jpg?width=1024"},{"name":"Aurora Borealis","rarity":"chase","id":"aurora-borealis","subtitle":"Aurora","details":"Aurora Borealis dances over Iceland when charged solar particles strike gases high in the atmosphere, painting the polar night sky green and violet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aurora%20Borealis%20-%20Iceland%20-%202%20Nov.%202013.jpg?width=1024"},{"name":"Ha Long Bay","rarity":"chase","id":"ha-long-bay","subtitle":"Bay","details":"Nearly 1,600 towering limestone karsts and islets rise from emerald Gulf of Tonkin waters, eroded over 300 million years into one of Earth's great seascapes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Halong_Bay_in_Vietnam.jpg?width=1024"},{"name":"Table Mountain","rarity":"chase","id":"table-mountain","subtitle":"Mountain","details":"This flat-topped mountain rises about 1,085 metres above Cape Town, its level summit plateau stretching roughly three kilometres from end to end.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Table_Mountain_DanieVDM.jpg?width=1024"},{"name":"Amazon Rainforest","rarity":"chase","id":"amazon-rainforest","subtitle":"Rainforest","details":"The Amazon is Earth's largest rainforest, sprawling across South America. Its dense green canopy shelters roughly one in ten of all known species alive today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Floresta%20amazonica.JPG?width=1024"},{"name":"Mount Kilimanjaro","rarity":"legendary","id":"mount-kilimanjaro","subtitle":"Mountain","details":"Africa's highest peak is a dormant volcano in Tanzania rising 5,895 metres, crowned by glaciers and Uhuru Peak above vast surrounding savanna plains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kilimanjaro_from_Amboseli.jpg?width=1024"},{"name":"Mount Fuji","rarity":"legendary","id":"mount-fuji","subtitle":"Volcano","details":"Japan's highest peak rises 3,776 metres in a near-perfect cone, a sacred volcano whose snow-capped summit has inspired artists for many centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_of_Mount_Fuji_from_%C5%8Cwakudani_20211202.jpg?width=1024"},{"name":"Matterhorn","rarity":"legendary","id":"matterhorn","subtitle":"Peak","details":"This pyramid-shaped Alpine peak rises 4,478 metres on the Swiss-Italian border, famed for its steep faces, sharp ridges and dramatic isolated profile.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Matterhorn_from_Domh%C3%BCtte_-_2.jpg?width=1024"},{"name":"Denali","rarity":"legendary","id":"denali","subtitle":"Mountain","details":"North America's highest peak rises 6,190 metres in Alaska, dominating its range with immense vertical relief and a summit often hidden by fierce storms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wonder_Lake_and_Denali.jpg?width=1024"},{"name":"Aconcagua","rarity":"legendary","id":"aconcagua","subtitle":"Mountain","details":"The highest mountain in the Americas rises 6,961 metres in Argentina's Andes, a massive non-technical peak battered by cold winds and dry high desert air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aconcagua2016.jpg?width=1024"},{"name":"Mount Etna","rarity":"legendary","id":"mount-etna","subtitle":"Volcano","details":"One of the world's most active volcanoes rises about 3,350 metres in Sicily, its frequent eruptions reshaping craters, lava fields and ash-covered slopes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mt_Etna_and_Catania1.jpg?width=1024"},{"name":"Angel Falls","rarity":"legendary","id":"angel-falls","subtitle":"Waterfall","details":"The world's tallest uninterrupted waterfall drops 807 metres from the Auyan Tepui plateau, with a total height of 979 metres including cascades below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SaltoAngel1.jpg?width=1024"},{"name":"Yosemite Falls","rarity":"legendary","id":"yosemite-falls","subtitle":"Waterfall","details":"Yosemite Creek drops 739 metres in three sections, including a 436-metre upper fall, a middle cascade and a 98-metre lower fall above the valley floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yosemite_falls_winter_2010.JPG?width=800"},{"name":"Gullfoss","rarity":"legendary","id":"gullfoss","subtitle":"Waterfall","details":"Glacial water from the Hvita River plunges in two broad tiers, first 11 metres and then 21 metres, into a rugged crevice that hides the base below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gullfoss_from_the_Air_%28cropped%29.jpg?width=1024"},{"name":"Detian Falls","rarity":"legendary","id":"detian-falls","subtitle":"Waterfall","details":"A wide, multi-tiered waterfall on the Quay Son River straddles a forested border valley, spreading about 300 metres across at its fullest flow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bangioc9tam.jpg?width=1024"},{"name":"Sahara","rarity":"legendary","id":"sahara","subtitle":"Desert","details":"The world's largest hot desert covers most of North Africa, an expanse of dunes, gravel plains and rocky plateaus nearly as large as the entire United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Erg%20Oriental%20Algeria.jpg?width=1024"},{"name":"Antelope Canyon","rarity":"legendary","id":"antelope-canyon","subtitle":"Canyon","details":"Flash floods carved this Arizona slot canyon's smooth, swirling sandstone walls, where narrow shafts of sunlight reach the sandy floor on bright midday hours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USA%20Antelope-Canyon.jpg?width=1024"},{"name":"Colca Canyon","rarity":"legendary","id":"colca-canyon","subtitle":"Canyon","details":"One of the deepest canyons on Earth, Peru's Colca cuts more than twice as deep as the Grand Canyon and is a famed refuge for soaring Andean condors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colca%20Canyon%20Puno.jpg?width=1024"},{"name":"Fish River Canyon","rarity":"legendary","id":"fish-river-canyon","subtitle":"Canyon","details":"Africa's largest canyon winds 100 miles through Namibia, a vast, rugged gorge carved by the Fish River into ancient rock over hundreds of millions of years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fish%20River%20Canyon%20from%20Main%20View%20Point.jpg?width=1024"},{"name":"Namib Desert","rarity":"legendary","id":"namib-desert","subtitle":"Desert","details":"Often called the world's oldest desert, the Namib has been arid for tens of millions of years, its giant red dunes marching to the Atlantic coast of Namibia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Duna%20en%20Sossusvlei%2C%20Namibia%2C%202018-08-06%2C%20DD%20002.jpg?width=1024"},{"name":"Lake Baikal","rarity":"legendary","id":"lake-baikal","subtitle":"Lake","details":"The world's deepest and oldest freshwater lake holds about a fifth of Earth's unfrozen surface fresh water in a vast Siberian rift basin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baikal%2C%20Cape%20Burhan%2C%20Olkhon%20Island%2C%20Lake%20Baikal%2C%20Russia.jpg?width=1024"},{"name":"Amazon River","rarity":"legendary","id":"amazon-river","subtitle":"River","details":"The Amazon carries more water than any other river on Earth, draining a vast rainforest basin before reaching the Atlantic Ocean in Brazil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meeting%20of%20Waters%20%28Manaus%29.jpg?width=1024"},{"name":"Nile River","rarity":"legendary","id":"nile-river","subtitle":"River","details":"Flowing north through northeastern Africa to the Mediterranean Sea, the Nile is one of the longest rivers on Earth, at about 6,650 kilometres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luxor%2C%20Egypt%2C%20River%20Nile%20sunset.jpg?width=1024"},{"name":"Cliffs of Moher","rarity":"legendary","id":"cliffs-of-moher","subtitle":"Cliff","details":"These sheer sea cliffs rise about 214 metres above the Atlantic Ocean in County Clare, Ireland, and stretch for roughly 14 kilometres of coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ireland%20cliffs%20of%20moher3%20Pumbaa80.jpg?width=1024"},{"name":"White Cliffs of Dover","rarity":"legendary","id":"white-cliffs-of-dover","subtitle":"Cliff","details":"Formed from pure white chalk laid down in a warm ancient sea, these famous cliffs face France across the narrowest part of the English Channel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White%20Cliffs%20of%20Dover%2002.JPG?width=1024"},{"name":"Mammoth Cave","rarity":"legendary","id":"mammoth-cave","subtitle":"Cave","details":"Kentucky's Mammoth Cave is the world's longest known cave system, with more than 420 miles of surveyed passageways winding beneath its green hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mammoth_Cave_Rotunda_%28USGS_Lwt02830%29.jpg?width=1024"},{"name":"Hang Sơn Đoòng","rarity":"legendary","id":"hang-son-doong","subtitle":"Cave","details":"Vietnam's Hang Son Doong is the largest cave on Earth by volume, so vast it holds a jungle, a river and clouds forming inside its enormous chambers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Son_Doong_Cave_DB_%281%29.jpg?width=1024"},{"name":"Carlsbad Caverns","rarity":"legendary","id":"carlsbad-caverns","subtitle":"Cavern","details":"New Mexico's Carlsbad Caverns holds the Big Room, one of the largest cave chambers in North America, filled with towering stalagmites and columns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Big_Room%2C_Carlsbad_Cavern_%2851202438416%29.jpg?width=1024"},{"name":"Congo Rainforest","rarity":"legendary","id":"congo-rainforest","subtitle":"Rainforest","details":"The Congo Basin holds the world's second-largest rainforest, a vast green heart of Africa crossed by slow rivers and home to forest elephants and bonobos.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BaAka%20camp%20in%20Dzanga-Sangha%20National%20Park%2C%20Central%20African%20Republic.jpg?width=1024"},{"name":"Redwood Forest","rarity":"legendary","id":"redwood-forest","subtitle":"Forest","details":"California's redwood forests shelter coast redwoods, the tallest trees on Earth. Some rise over 350 feet and have stood for more than two thousand years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Redwood%20National%20Park%2C%20fog%20in%20the%20forest.jpg?width=1024"},{"name":"Daintree Rainforest","rarity":"legendary","id":"daintree-rainforest","subtitle":"Rainforest","details":"Australia's Daintree is among the oldest rainforests on Earth, a living relic of the ancient Gondwanan forests that once covered the southern continents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Daintree%20Rainforest%2C%20Queensland%20%28483843%29%20%289443586080%29.jpg?width=1024"},{"name":"Black Forest","rarity":"legendary","id":"black-forest","subtitle":"Forest","details":"Germany's Black Forest, the Schwarzwald, is a mountainous sea of dark spruce and fir, famous for cuckoo clocks, deep gorges and the source of the Danube.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blick%20vom%20Hohfelsen.jpg?width=1024"},{"name":"Perito Moreno Glacier","rarity":"legendary","id":"perito-moreno-glacier","subtitle":"Glacier","details":"In Argentina's Patagonia, this huge glacier advances into Lago Argentino and calves towering icebergs, one of the world's few still-growing glaciers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Perito%20Moreno%20Glacier%20Patagonia%20Argentina%20Luca%20Galuzzi%202005.JPG?width=1024"},{"name":"Grand Prismatic Spring","rarity":"legendary","id":"grand-prismatic-spring","subtitle":"Hot Spring","details":"Yellowstone's largest hot spring glows in rainbow rings of heat-loving bacteria, its steaming blue center hotter than most life can survive in water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20prismatic%20spring.jpg?width=1024"},{"name":"Galapagos Islands","rarity":"legendary","id":"galapagos-islands","subtitle":"Archipelago","details":"Volcanic islands astride the equator whose isolated finches, tortoises and iguanas helped Darwin shape his theory of evolution by natural selection in 1835.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bartolom%C3%A9_Island_Pinnacle_Rock.jpg?width=1024"},{"name":"Mount Vesuvius","rarity":"epic","id":"mount-vesuvius","subtitle":"Volcano","details":"This Italian volcano overlooking the Bay of Naples is famed for its eruption in AD 79, which buried the Roman cities of Pompeii and Herculaneum in ash.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Il_cratere_del_Vulcano_-_panoramio.jpg?width=1024"},{"name":"K2","rarity":"epic","id":"k2","subtitle":"Mountain","details":"The world's second-highest mountain rises 8,611 metres in the Karakoram, renowned among climbers for steep ice, unstable weather and severe technical danger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chogori.jpg?width=1024"},{"name":"Mont Blanc","rarity":"epic","id":"mont-blanc","subtitle":"Mountain","details":"Western Europe's highest peak rises 4,808 metres in the Alps on the French-Italian border, a vast dome of rock, snowfields and crevassed glaciers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mont_Blanc_Aiguille.jpg?width=1024"},{"name":"Mount Rainier","rarity":"epic","id":"mount-rainier","subtitle":"Volcano","details":"This heavily glaciated volcano rises 4,392 metres in Washington, carrying more glacial ice than any other single peak in the contiguous United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rainier20200906.jpg?width=1024"},{"name":"Mount Ararat","rarity":"epic","id":"mount-ararat","subtitle":"Volcano","details":"This snow-capped dormant volcano rises 5,137 metres in eastern Turkey, formed by two cones and long revered as a sacred and storied national symbol.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Ararat_and_the_Yerevan_skyline_in_spring_%2850mm%29.jpg?width=1024"},{"name":"Eiger","rarity":"epic","id":"eiger","subtitle":"Mountain","details":"This Swiss Alpine peak rises 3,967 metres, notorious for its towering north face, a sheer wall of rock and ice that challenges expert mountaineers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/North_face.jpg?width=1024"},{"name":"Mount Kenya","rarity":"epic","id":"mount-kenya","subtitle":"Mountain","details":"Africa's second-highest mountain rises 5,199 metres in Kenya, an eroded extinct volcano with jagged twin peaks, glaciers and rare high alpine plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Batian%20Peak.JPG?width=1024"},{"name":"Mount Cook","rarity":"epic","id":"mount-cook","subtitle":"Mountain","details":"New Zealand's highest mountain rises 3,724 metres in the Southern Alps, a steep ice-clad peak known locally by its Maori name, Aoraki, meaning cloud piercer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mt_Cook_LC0247.jpg?width=1024"},{"name":"Kaieteur Falls","rarity":"epic","id":"kaieteur-falls","subtitle":"Waterfall","details":"The Potaro River makes a single sheer drop of 226 metres over a sandstone cliff, then rushes through rapids in the rainforest of Kaieteur National Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GuyanaKaieteurFalls2004.jpg?width=1024"},{"name":"Tugela Falls","rarity":"epic","id":"tugela-falls","subtitle":"Waterfall","details":"A series of five leaps on the Tugela River drops about 948 metres from the Drakensberg escarpment, making it one of the tallest waterfalls on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tugela_falls.jpg?width=800"},{"name":"Multnomah Falls","rarity":"epic","id":"multnomah-falls","subtitle":"Waterfall","details":"Spring-fed water drops 189 metres in two tiers in the Columbia River Gorge, passing beneath a distinctive stone bridge built across its middle reach.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Multnomah_Falls_on_2_August_2012.jpg?width=800"},{"name":"Huangguoshu Waterfall","rarity":"epic","id":"huangguoshu-waterfall","subtitle":"Waterfall","details":"The Baishui River drops 78 metres over a cliff about 101 metres wide, and a cave behind the falling curtain lets visitors stand behind the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E9%BB%84%E6%9E%9C%E6%A0%91%E7%80%91%E5%B8%83_2026-07-31_01.jpg?width=1024"},{"name":"Rhine Falls","rarity":"epic","id":"rhine-falls","subtitle":"Waterfall","details":"The Rhine pours over a rocky ledge about 150 metres wide and 23 metres high, making this the largest plain waterfall in Europe by volume of flow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhine_Falls_in_Switzerland.jpg?width=1024"},{"name":"Havasu Falls","rarity":"epic","id":"havasu-falls","subtitle":"Waterfall","details":"Blue-green, mineral-rich water from Havasu Creek drops about 30 metres into travertine pools in a red-rock side canyon of the Grand Canyon system.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New_havasu_falls.JPG?width=1024"},{"name":"Verdon Gorge","rarity":"epic","id":"verdon-gorge","subtitle":"Gorge","details":"France's Verdon River carved this turquoise limestone gorge up to 2,300 feet deep, one of Europe's grandest canyons and a haven for climbers and kayakers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Verdon%20Gorge%201.jpg?width=1024"},{"name":"Blyde River Canyon","rarity":"epic","id":"blyde-river-canyon","subtitle":"Canyon","details":"One of the world's largest green canyons, South Africa's Blyde River Canyon stretches 16 miles beneath lush subtropical cliffs and the Three Rondavels peaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blyde%20River%20Canyon%20Nature%20Reserve%20%28ZA%29%2C%20Lowveld%20View%2C%20Blyde%20River%20--%202024%20--%209964.jpg?width=800"},{"name":"Yarlung Tsangpo Grand Canyon","rarity":"epic","id":"yarlung-tsangpo-grand-canyon","subtitle":"Canyon","details":"The world's deepest canyon plunges over 17,000 feet in Tibet, where the Yarlung Tsangpo River bends sharply around the Himalayan peak Namcha Barwa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yarlung%20Zangpo%20Grand%20Canyon%2C%20Tibet.jpg?width=1024"},{"name":"Wadi Rum","rarity":"epic","id":"wadi-rum","subtitle":"Desert","details":"Jordan's vast desert valley of towering sandstone mountains and red sand was carved by ancient rivers and has sheltered travellers for thousands of years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mountain%20in%20Wadi%20Rum%2C%20Jordan.jpg?width=1024"},{"name":"Atacama Desert","rarity":"epic","id":"atacama-desert","subtitle":"Desert","details":"The driest nonpolar desert on Earth, Chile's Atacama can go years without rain, leaving salt flats, geysers and valleys that closely resemble Mars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anfiteatro%2C%20Valle%20de%20la%20Luna%2C%20San%20Pedro%20de%20Atacama%2C%20Chile%2C%202016-02-01%2C%20DD%20149.JPG?width=1024"},{"name":"Tara River Canyon","rarity":"epic","id":"tara-river-canyon","subtitle":"Canyon","details":"Europe's deepest river canyon drops some 4,300 feet in Montenegro, where the emerald Tara River races through the wild forests of Durmitor National Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tara%20River%20Canyon.jpg?width=1024"},{"name":"Kings Canyon","rarity":"epic","id":"kings-canyon","subtitle":"Canyon","details":"Ancient sandstone walls rise 300 feet above a permanent waterhole in Australia's Watarrka National Park, a sacred place for the Luritja people for millennia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kings%20Canyon%20NT%20view.jpg?width=1024"},{"name":"Lake Superior","rarity":"epic","id":"lake-superior","subtitle":"Lake","details":"The largest freshwater lake in the world by surface area, Superior is the biggest, coldest and deepest of North America's five Great Lakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gfp-michigan-pictured-rocks-national-lakeshore-scenic-shoreline.jpg?width=1024"},{"name":"Yangtze River","rarity":"epic","id":"yangtze-river","subtitle":"River","details":"Asia's longest river flows about 6,300 kilometres across China, from high Tibetan glaciers eastward to the East China Sea near Shanghai.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Three%20gorges%20on%20the%20Yangtze%20river.jpg?width=1024"},{"name":"Mississippi River","rarity":"epic","id":"mississippi-river","subtitle":"River","details":"North America's great central river flows about 3,730 kilometres from Minnesota's Lake Itasca south to the Gulf of Mexico below New Orleans.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mississippi%20River%20View%20from%20Brady%27s%20Bluff.jpg?width=1024"},{"name":"Lake Titicaca","rarity":"epic","id":"lake-titicaca","subtitle":"Lake","details":"Straddling Peru and Bolivia at about 3,812 metres above sea level, Titicaca is the world's highest lake navigable to large vessels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Titicaca%20on%20the%20Andes%20from%20Bolivia.jpg?width=800"},{"name":"Danube River","rarity":"epic","id":"danube-river","subtitle":"River","details":"Europe's second-longest river flows about 2,850 kilometres through ten countries, from Germany's Black Forest to a broad delta on the Black Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vineyards%20along%20the%20Danube%20in%20Wachau.jpg?width=1024"},{"name":"Big Sur","rarity":"epic","id":"big-sur","subtitle":"Coast","details":"Where California's Santa Lucia Mountains meet the Pacific Ocean, this rugged, sparsely settled coastline is famed for redwoods, fog and surf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Big%20Sur%2C%20Pacific%20Coast%2C%20California%2C%20USA9.jpg?width=1024"},{"name":"Na Pali Coast","rarity":"epic","id":"na-pali-coast","subtitle":"Coast","details":"Kauai's remote northwest shore is a wall of emerald sea cliffs, hanging valleys and secluded beaches, reachable only by boat, air or a rugged trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Na%20Pali%20Coast.jpg?width=1024"},{"name":"Waitomo Glowworm Caves","rarity":"epic","id":"waitomo-glowworm-caves","subtitle":"Cave","details":"New Zealand's Waitomo Caves glow with thousands of living glowworms, whose blue-green lights reflect on an underground river toured silently by boat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Glowworm_Grotto%2C_Waitomo_Glowworm_Cave.jpg?width=1024"},{"name":"Reed Flute Cave","rarity":"epic","id":"reed-flute-cave","subtitle":"Cave","details":"China's Reed Flute Cave in Guilin glitters with stalactites lit in bright colours, its rock shapes named for poems, mythical beasts and landscapes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reed_Flute_Cave_89013-Guilin_%2844934930442%29.jpg?width=1024"},{"name":"Postojna Cave","rarity":"epic","id":"postojna-cave","subtitle":"Cave","details":"Slovenia's Postojna Cave stretches over 24 kilometres, and visitors ride a small train past grand halls where the pale human fish lives in darkness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Postojna_cave_2008-02-01_interior_01.jpg?width=800"},{"name":"Jeita Grotto","rarity":"epic","id":"jeita-grotto","subtitle":"Grotto","details":"Lebanon's Jeita Grotto holds two levels of glittering limestone galleries, the lower one crossed by boat along a clear underground river in silence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Upper_Jeita_Grotto.jpg?width=1024"},{"name":"Sundarbans","rarity":"epic","id":"sundarbans","subtitle":"Mangrove","details":"The Sundarbans is the world's largest mangrove forest, a tidal maze of roots and channels where Bengal tigers swim between islands in the Ganges delta.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dense%20Mangrove%20Forest%20of%20the%20Sundarban%20Tiger%20Reserve%20during%20High%20Tide%2C%20West%20Bengal%2C%20India%2002.jpg?width=1024"},{"name":"Bialowieza Forest","rarity":"epic","id":"bialowieza-forest","subtitle":"Forest","details":"Bialowieza, on the Poland-Belarus border, is Europe's last great primeval lowland forest, where wild European bison roam among oaks centuries old.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bialowieza%20National%20Park%20in%20Poland0029.JPG?width=1024"},{"name":"Tongass National Forest","rarity":"epic","id":"tongass-national-forest","subtitle":"Forest","details":"Alaska's Tongass is the largest national forest in the United States, a temperate rainforest of spruce and cedar draped over fjords and island shores.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hall%20of%20Giants%20Tongass%20NRT%20photo%2007%20%2852502997859%29.jpg?width=1024"},{"name":"Great Bear Rainforest","rarity":"epic","id":"great-bear-rainforest","subtitle":"Rainforest","details":"British Columbia's Great Bear Rainforest is one of the largest intact coastal temperate rainforests left, home to the rare white spirit bear.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pacific%20skyline%2C%20Kitlope%20Heritage%20Conservancy.jpg?width=1024"},{"name":"Borneo Rainforest","rarity":"epic","id":"borneo-rainforest","subtitle":"Rainforest","details":"Borneo's rainforests are among the oldest and richest on Earth, where towering dipterocarp trees shelter orangutans, hornbills and pygmy elephants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morning%20fog%20over%20Danum%20Valley%20%2827329938517%29.jpg?width=1024"},{"name":"Yakushima Forest","rarity":"epic","id":"yakushima-forest","subtitle":"Forest","details":"Japan's Yakushima island forest is a moss-draped world of ancient sugi cedars, where some trees, called yakusugi, are thousands of years old.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shiratani%20Unsui%20Gorge%2001.jpg?width=1024"},{"name":"Old Faithful","rarity":"epic","id":"old-faithful","subtitle":"Geyser","details":"Yellowstone's famous geyser erupts with remarkable regularity, blasting steaming water high into the air about twenty times every single day of the year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yellowstone%20National%20Park%20%28WY%2C%20USA%29%2C%20Old%20Faithful%20Geyser%20--%202022%20--%202592.jpg?width=1024"},{"name":"Aurora Australis","rarity":"epic","id":"aurora-australis","subtitle":"Aurora","details":"The southern lights ripple over Antarctica and the far south, the mirror image of the aurora borealis, glowing green and pink above the polar night sky.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aurora%20Australis%20Over%20the%20Tasman%20Sea%20from%20SouthWest%20National%20Park.jpg?width=1024"},{"name":"Catatumbo Lightning","rarity":"epic","id":"catatumbo-lightning","subtitle":"Phenomenon","details":"Over Venezuela's Lake Maracaibo, lightning storms flash on up to 260 nights a year, the most frequent lightning display anywhere on planet Earth today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Catatumbo%20Lightning%20-%20Rayo%20del%20Catatumbo.jpg?width=1024"},{"name":"Jakobshavn Glacier","rarity":"epic","id":"jakobshavn-glacier","subtitle":"Glacier","details":"Greenland's fastest major glacier flows toward Disko Bay, calving enormous icebergs, including one long said to have sunk the Titanic in the North Atlantic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/023%20Aerial%20view%20of%20Jakobshavn%20Glacier%20at%20Disko%20Bay%20%28Greenland%29%20Photo%20by%20Giles%20Laurent.jpg?width=1024"},{"name":"Raja Ampat Islands","rarity":"epic","id":"raja-ampat-islands","subtitle":"Archipelago","details":"A maze of jungle-topped limestone islets off New Guinea holding the richest coral reef biodiversity on Earth, with over 1,600 fish species recorded here.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Piaynemo_Island%2C_Raja_Ampat%2C_West_Papua%2C_Indonesia.jpg?width=1024"},{"name":"Great Blue Hole","rarity":"epic","id":"great-blue-hole","subtitle":"Sinkhole","details":"A perfectly circular marine sinkhole 318 metres wide and 124 metres deep off Belize, formed in a drowned Ice Age cave and ringed by pale coral shallows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great_Blue_Hole.jpg?width=1024"},{"name":"Palau Rock Islands","rarity":"epic","id":"palau-rock-islands","subtitle":"Lagoon","details":"Some 445 mushroom-shaped limestone islands rise from a turquoise lagoon in Palau, their undercut bases sculpted by waves, boring clams and sponges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rock-Islands-Palau-1-2016-aerial-view-Luka-Peternel.jpg?width=1024"},{"name":"Socotra","rarity":"epic","id":"socotra","subtitle":"Island","details":"Isolated in the Arabian Sea for millions of years, Socotra evolved alien-looking dragon's blood trees and a third of its plants are found nowhere else.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Socotra_dragon_tree.JPG?width=1024"},{"name":"Mount Elbrus","rarity":"rare","id":"mount-elbrus","subtitle":"Mountain","details":"Europe's highest peak rises 5,642 metres in Russia's Caucasus Mountains, a dormant twin-coned volcano cloaked in broad snowfields and glaciers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Elbrus_%28cropped%29.jpg?width=1024"},{"name":"Kangchenjunga","rarity":"rare","id":"kangchenjunga","subtitle":"Mountain","details":"The world's third-highest mountain rises 8,586 metres on the Nepal-India border, a vast massif of five summits, glaciers and remote avalanche-prone valleys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kangchenjunga_PangPema.JPG?width=1024"},{"name":"Mount Whitney","rarity":"rare","id":"mount-whitney","subtitle":"Mountain","details":"The highest peak in the contiguous United States rises 4,421 metres in California's Sierra Nevada, a granite summit reached by a famous winding trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Whitney_2003-03-25.jpg?width=1024"},{"name":"Mount Hood","rarity":"rare","id":"mount-hood","subtitle":"Volcano","details":"This glaciated Oregon volcano rises 3,429 metres, its sharp summit pyramid holding year-round snowfields and large ski areas on its forested slopes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oregon_Mount_Hood_from_Trillium_Lake_2024.jpg?width=1024"},{"name":"Mount Shasta","rarity":"rare","id":"mount-shasta","subtitle":"Volcano","details":"This California volcano rises 4,322 metres above surrounding plains, a solitary glacier-draped cone with a smaller satellite cone called Shastina on its flank.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MtShasta_aerial.JPG?width=1024"},{"name":"Ben Nevis","rarity":"rare","id":"ben-nevis","subtitle":"Mountain","details":"Britain's highest mountain rises 1,345 metres in Scotland, its summit ruins and sheer north cliffs often wrapped in cloud above the glens around Fort William.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BenNevis2005.jpg?width=1024"},{"name":"Mount Olympus","rarity":"rare","id":"mount-olympus","subtitle":"Mountain","details":"Greece's highest mountain rises 2,917 metres near the Aegean coast, its craggy Mytikas summit famed in mythology as the home of the twelve Olympian gods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olympus_National_Park_30.jpg?width=1024"},{"name":"Snowdon","rarity":"rare","id":"snowdon","subtitle":"Mountain","details":"Wales' highest mountain, known in Welsh as Yr Wyddfa, rises 1,085 metres in Eryri, with rocky ridges, glacial lakes and views across Snowdonia's peaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snowdon_massif.jpg?width=1024"},{"name":"Mount Toubkal","rarity":"rare","id":"mount-toubkal","subtitle":"Mountain","details":"North Africa's highest peak rises 4,167 metres in Morocco's High Atlas, a rugged summit above Berber villages, scree slopes and deep mountain valleys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/My_Toubkal.jpg?width=1024"},{"name":"Mount Roraima","rarity":"rare","id":"mount-roraima","subtitle":"Mountain","details":"This sheer-sided tepui rises about 2,810 metres where Venezuela, Brazil and Guyana meet, its flat top often wreathed in cloud above tropical savanna.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roraima3_%2879%29.JPG?width=1024"},{"name":"Mount Bromo","rarity":"rare","id":"mount-bromo","subtitle":"Volcano","details":"This active Indonesian volcano rises 2,329 metres inside a vast sea of sand in Java, its smoking crater rim glowing at sunrise above the caldera floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bromo-Semeru-Batok-Widodaren.jpg?width=1024"},{"name":"Mauna Loa","rarity":"rare","id":"mauna-loa","subtitle":"Volcano","details":"One of Earth's largest volcanoes rises 4,169 metres above sea level in Hawaii, a broad shield built by fluid lava flows stacking over immense distances.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mauna_Loa_Volcano.jpg?width=1024"},{"name":"Dettifoss","rarity":"rare","id":"dettifoss","subtitle":"Waterfall","details":"Glacial meltwater from the Jokulsa a Fjollum drops 44 metres over a 100-metre-wide basalt lip, giving it a famously powerful flow for its size.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dettifoss_TimBekaert.JPG?width=1024"},{"name":"Skogafoss","rarity":"rare","id":"skogafoss","subtitle":"Waterfall","details":"The Skoga River falls 60 metres over a former sea cliff in a near-perfect rectangle about 25 metres wide, throwing up spray that often forms rainbows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2008-05-24_35_Sk%C3%B3gafoss.jpg?width=1024"},{"name":"Seljalandsfoss","rarity":"rare","id":"seljalandsfoss","subtitle":"Waterfall","details":"The Seljalands River drops about 60 metres over an old coastline cliff, and a path leads behind the curtain into a shallow cave behind the fall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Idyllic_landscape_with_a_waterfall_%28Unsplash%29.jpg?width=1024"},{"name":"Snoqualmie Falls","rarity":"rare","id":"snoqualmie-falls","subtitle":"Waterfall","details":"The Snoqualmie River drops 82 metres over a granite ledge, higher than Niagara, into a misty gorge surrounded by evergreen forest and a historic lodge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snoqualmie_Falls%2C_Snoqualmie%2C_WA.jpeg?width=1024"},{"name":"Jog Falls","rarity":"rare","id":"jog-falls","subtitle":"Waterfall","details":"The Sharavati River splits into four named streams, Raja, Rani, Roarer and Rocket, that plunge about 253 metres over a cliff in a single great leap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jog_Falls_05092016.jpg?width=1024"},{"name":"Krimml Waterfalls","rarity":"rare","id":"krimml-waterfalls","subtitle":"Waterfall","details":"The Krimmler Ache tumbles about 380 metres in three main tiers through a forested Alpine valley, making this the highest waterfall system in Austria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Austrian.waterfall.at.krimml.arp.jpg?width=1024"},{"name":"Gocta Falls","rarity":"rare","id":"gocta-falls","subtitle":"Waterfall","details":"A two-tiered fall in cloud forest drops about 771 metres in total, with its taller upper leap and lower leap long known to people living nearby.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Catarata_de_Gocta%2C_2023_%2803%29.jpg?width=1024"},{"name":"Akaka Falls","rarity":"rare","id":"akaka-falls","subtitle":"Waterfall","details":"Kolekole Stream plunges 135 metres over a volcanic cliff into a fern-filled gorge, in a rainforest where heliconia, orchids and bamboo crowd the trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Akaka_Falls%2C_Hawaii_Island%2C_USA2.jpg?width=800"},{"name":"Ouzoud Falls","rarity":"rare","id":"ouzoud-falls","subtitle":"Waterfall","details":"The El Abid River drops about 110 metres in stepped cascades over red sandstone, framed by olive groves whose Berber name gives the falls their name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ouzoud_waterfalls_from_below.jpeg?width=1024"},{"name":"Dynjandi","rarity":"rare","id":"dynjandi","subtitle":"Waterfall","details":"A fan-shaped fall widens from about 30 metres at the top to 60 metres at the base as it spills 100 metres down a mountainside in many veiled streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cascada_Dynjandi%2C_Vestfir%C3%B0ir%2C_Islandia%2C_2014-08-14%2C_DD_136-138_HDR.JPG?width=800"},{"name":"Hells Canyon","rarity":"rare","id":"hells-canyon","subtitle":"Canyon","details":"North America's deepest river gorge drops nearly 8,000 feet along the Snake River on the Idaho-Oregon border, deeper even than the famous Grand Canyon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/OR%20hells%20canyon.jpg?width=1024"},{"name":"Waimea Canyon","rarity":"rare","id":"waimea-canyon","subtitle":"Canyon","details":"Called the Grand Canyon of the Pacific, Hawaii's Waimea Canyon stretches 14 miles across Kauai in layers of red, green and brown volcanic rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Waimea%20Canyon%2C%20Kauai%2C%20Hawaii.jpg?width=1024"},{"name":"Copper Canyon","rarity":"rare","id":"copper-canyon","subtitle":"Canyon","details":"Mexico's Copper Canyon system is a network of six great canyons in Chihuahua that together cover an area four times larger than the Grand Canyon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barranca%20del%20cobre%202.jpg?width=1024"},{"name":"Kali Gandaki Gorge","rarity":"rare","id":"kali-gandaki-gorge","subtitle":"Gorge","details":"One of the world's deepest gorges, Nepal's Kali Gandaki slices between the Himalayan giants Dhaulagiri and Annapurna along an ancient trade route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kowang%2C%20Kali%20Gandaki%20Gorge%2C%20Nepal.jpg?width=1024"},{"name":"Tiger Leaping Gorge","rarity":"rare","id":"tiger-leaping-gorge","subtitle":"Gorge","details":"China's Jinsha River roars through this narrow Yunnan gorge beneath snow peaks, named for a legend of a tiger leaping across its churning rapids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yunnan%20China%20Tiger-Leaping-Gorge-07.jpg?width=1024"},{"name":"Rub' al Khali","rarity":"rare","id":"rub-al-khali","subtitle":"Desert","details":"The Empty Quarter is the world's largest continuous sand desert, a sea of dunes up to 800 feet high spanning four countries of the Arabian Peninsula.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rub%20al-Khali%20Oman%201.jpg?width=1024"},{"name":"Gobi Desert","rarity":"rare","id":"gobi-desert","subtitle":"Desert","details":"Asia's great cold desert spans Mongolia and China, a land of gravel plains, singing dunes and dinosaur fossils where winters plunge far below freezing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gobi%20Desert%20dunes.jpg?width=1024"},{"name":"Zion Canyon","rarity":"rare","id":"zion-canyon","subtitle":"Canyon","details":"Utah's Virgin River carved Zion Canyon's towering red and cream sandstone walls, a 15-mile gorge of hanging gardens, narrows and sheer cliff faces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zion%20Canyon%20from%20Angels%20Landing.jpg?width=800"},{"name":"Canyon de Chelly","rarity":"rare","id":"canyon-de-chelly","subtitle":"Canyon","details":"Arizona's red-walled canyon shelters ancient cliff dwellings and remains home to Navajo families who still farm the canyon floor as their ancestors did.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canyon%20de%20Chelly%20National%20Monument.jpg?width=1024"},{"name":"Charyn Canyon","rarity":"rare","id":"charyn-canyon","subtitle":"Canyon","details":"Kazakhstan's Charyn River carved a 56-mile canyon of fantastical red rock towers and castles through the steppe near the border with China.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charyn%20Canyon%2C%20Kazakhstan%2003.jpg?width=1024"},{"name":"Palo Duro Canyon","rarity":"rare","id":"palo-duro-canyon","subtitle":"Canyon","details":"The second-largest canyon in the United States cuts 120 miles through the Texas Panhandle in bands of red, orange and lavender rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palo%20Duro%20Canyon%20and%20Capitol%20Peak.JPG?width=1024"},{"name":"Caspian Sea","rarity":"rare","id":"caspian-sea","subtitle":"Lake","details":"The largest enclosed body of water on Earth, this vast salt lake between Europe and Asia covers more area than the whole country of Japan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coast%20of%20Caspian%20Sea%20-%20Iran.jpg?width=1024"},{"name":"Lake Victoria","rarity":"rare","id":"lake-victoria","subtitle":"Lake","details":"Africa's largest lake by area and the chief reservoir of the Nile, Victoria touches Tanzania, Uganda and Kenya and supports huge fisheries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shores%20of%20Lake%20Victoria%20at%20Ssese%20Islands.jpg?width=1024"},{"name":"Congo River","rarity":"rare","id":"congo-river","subtitle":"River","details":"Africa's second-longest river carries the continent's greatest flow, winding through dense rainforest to the Atlantic Ocean near Boma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Congo%20River%20near%20Kisangani.jpg?width=1024"},{"name":"Rhine River","rarity":"rare","id":"rhine-river","subtitle":"River","details":"From Swiss Alpine glaciers the Rhine flows about 1,230 kilometres through the castled Rhine Gorge and the lowlands to the sea at Rotterdam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhine%20River%20at%20Lorelei%20Middle%20Rhine%20valley%20Germany.jpg?width=1024"},{"name":"Lake Bled","rarity":"rare","id":"lake-bled","subtitle":"Lake","details":"A glacial lake in Slovenia's Julian Alps, Bled is famed for its small wooded island crowned by a church and a castle on a cliff above it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sunrise%20at%20Lake%20Bled.jpg?width=1024"},{"name":"Moraine Lake","rarity":"rare","id":"moraine-lake","subtitle":"Lake","details":"Fed by glacial melt in Banff National Park, this Alberta lake glows a vivid turquoise from fine rock flour carried down by surrounding glaciers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moraine%20Lake%2017092005.jpg?width=1024"},{"name":"Amalfi Coast","rarity":"rare","id":"amalfi-coast","subtitle":"Coast","details":"Italy's famed Amalfi Coast stacks pastel villages on steep cliffs above the Tyrrhenian Sea, linked by a famously winding coastal road.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20Coast%20%28Positano%29.jpg?width=1024"},{"name":"Jurassic Coast","rarity":"rare","id":"jurassic-coast","subtitle":"Coast","details":"England's Jurassic Coast exposes 185 million years of rock history in its cliffs and bays, from Triassic red sandstone to Cretaceous chalk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Durdle%20Door%20-%20Jurassic%20Coast.jpg?width=1024"},{"name":"Dead Sea","rarity":"rare","id":"dead-sea","subtitle":"Lake","details":"Bordering Jordan and Israel, this hypersaline lake sits at the lowest land elevation on Earth and is nearly ten times saltier than the ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dead%20Sea%2C%20Jordan%2002.jpg?width=1024"},{"name":"Lake Como","rarity":"rare","id":"lake-como","subtitle":"Lake","details":"Shaped like an inverted Y in Italy's Lombardy region, deep glacial Lake Como has been a celebrated retreat beneath Alpine foothills since Roman times.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Como%20Lake%20from%20Bellagio.jpg?width=1024"},{"name":"Mekong River","rarity":"rare","id":"mekong-river","subtitle":"River","details":"Southeast Asia's great river flows about 4,500 kilometres from the Tibetan Plateau through six countries to a vast delta in southern Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mountains%20Mekong%20river%20and%20dwellings%20seen%20from%20Mount%20Phou%20Si%20at%20dusk%20in%20Luang%20Prabang%20Laos.jpg?width=1024"},{"name":"Cave of the Crystals","rarity":"rare","id":"cave-of-the-crystals","subtitle":"Cave","details":"Mexico's Cave of the Crystals holds the largest natural crystals ever found, giant clear gypsum beams up to 12 metres long grown in hot, flooded heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cristales_cueva_de_Naica.JPG?width=1024"},{"name":"Škocjan Caves","rarity":"rare","id":"skocjan-caves","subtitle":"Cave","details":"Slovenia's Skocjan Caves enclose one of the largest underground canyons on Earth, where the Reka River thunders far below a natural rock bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skocjan_Caves_%283802558032%29.jpg?width=1024"},{"name":"Fingal's Cave","rarity":"rare","id":"fingals-cave","subtitle":"Cave","details":"Scotland's Fingal's Cave on Staffa is framed by perfect hexagonal basalt columns, and its arched roof gives the crashing Atlantic surf a cathedral echo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fingal%27s_Cave_Interior.jpg?width=1024"},{"name":"Eisriesenwelt","rarity":"rare","id":"eisriesenwelt","subtitle":"Cave","details":"Austria's Eisriesenwelt is the world's largest ice cave, a 42-kilometre labyrinth where frozen waterfalls and towering ice figures fill its cold halls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eisriesenwelt_Werfen_Austria_02.jpg?width=1024"},{"name":"Phong Nha Cave","rarity":"rare","id":"phong-nha-cave","subtitle":"Cave","details":"Vietnam's Phong Nha Cave stretches nearly 8 kilometres underground, entered by boat along a river that passes grottoes hung with huge stalactites.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phong_Nha-Ke_Bang_cave3.jpg?width=1024"},{"name":"Puerto Princesa Underground River","rarity":"rare","id":"puerto-princesa-underground-river","subtitle":"Underground River","details":"The Philippines' Puerto Princesa Underground River flows 8.2 kilometres through a vast cave before emerging straight into the sea on Palawan Island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Puerto_Princesa_Subterranean_River_-_PuertoPrincesaSR1755.jpg?width=1024"},{"name":"Lascaux Cave","rarity":"rare","id":"lascaux-cave","subtitle":"Cave","details":"France's Lascaux Cave preserves vivid Ice Age paintings of horses, deer and aurochs, drawn on its walls more than 17,000 years ago by early hunters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lascaux%2C_Megaloceros.jpg?width=1024"},{"name":"Monteverde Cloud Forest","rarity":"rare","id":"monteverde-cloud-forest","subtitle":"Forest","details":"Costa Rica's Monteverde sits high in the mountains, wrapped in near-constant cloud and mist that nourish orchids, mosses and the resplendent quetzal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monteverde%20bosque.jpg?width=1024"},{"name":"Giant Forest","rarity":"rare","id":"giant-forest","subtitle":"Grove","details":"California's Giant Forest holds groves of giant sequoias, including the General Sherman Tree, the largest known living single-stem tree on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giganteum%20Sequoiadendron%202019.jpg?width=1024"},{"name":"Arashiyama Bamboo Grove","rarity":"rare","id":"arashiyama-bamboo-grove","subtitle":"Grove","details":"Kyoto's Arashiyama Bamboo Grove is a towering forest of moso bamboo, where tall green culms sway and creak above one of Japan's most famous paths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bamboo%20Forest%2C%20Arashiyama%2C%20Kyoto%2C%20Japan.jpg?width=1024"},{"name":"Valdivian Temperate Rainforest","rarity":"rare","id":"valdivian-temperate-rainforest","subtitle":"Rainforest","details":"Chile's Valdivian rainforest is a cool, rain-soaked forest of alerce and monkey puzzle relatives, isolated for ages between the Andes and the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Valdivian%20temperate%20rainforest.JPG?width=1024"},{"name":"Sinharaja Rainforest","rarity":"rare","id":"sinharaja-rainforest","subtitle":"Rainforest","details":"Sri Lanka's Sinharaja is a dense, emerald rainforest reserve where most trees are found nowhere else, and mixed flocks of birds move through the canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SL%20Sinharaja%20Forest%20asv2020-01%20img08.jpg?width=1024"},{"name":"Tarkine Rainforest","rarity":"rare","id":"tarkine-rainforest","subtitle":"Rainforest","details":"Tasmania's Tarkine is one of the world's great cool temperate rainforests, a wild green expanse of myrtle beech, tree ferns and untamed rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hellyer%20Gorge%2C%20Tasmania.jpg?width=1024"},{"name":"Waipoua Forest","rarity":"rare","id":"waipoua-forest","subtitle":"Forest","details":"New Zealand's Waipoua Forest protects giant kauri trees, including Tane Mahuta, the Lord of the Forest, a colossal tree sacred to the Maori people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oldest%20Kauri%20tree%2C%20Waipoua%20Forest%2C%20North%20Island%2C%20New%20Zealand%20-%20panoramio.jpg?width=800"},{"name":"Hallerbos Forest","rarity":"rare","id":"hallerbos-forest","subtitle":"Forest","details":"Belgium's Hallerbos is a beech forest famous each spring when millions of bluebells carpet its floor in a vivid blue beneath the new green canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hallerbos%20%2826787455905%29.jpg?width=1024"},{"name":"Hoh Rainforest","rarity":"rare","id":"hoh-rainforest","subtitle":"Rainforest","details":"The Hoh Rainforest in Olympic National Park is one of America's finest temperate rainforests, where moss hangs from bigleaf maples in green curtains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BIG%20LEAF%20MAPLES%20HOH.jpg?width=1024"},{"name":"Mendenhall Glacier","rarity":"rare","id":"mendenhall-glacier","subtitle":"Glacier","details":"Near Juneau, Alaska, this thirteen-mile glacier pours from the Juneau Icefield, its blue face calving into a lake visited by bears, goats and porcupines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mendenhall%20Glacier%20-%202021-01-19.jpg?width=1024"},{"name":"Jökulsárlón","rarity":"rare","id":"jokulsarlon","subtitle":"Lagoon","details":"Iceland's famous glacier lagoon fills with blue icebergs calved from Breidamerkurjokull, drifting slowly to sea and washing ashore on a black sand beach.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%B6kuls%C3%A1rl%C3%B3n%20glacier%20lagoon%2C%20Iceland%2C%2020240718%201607%202323.jpg?width=1024"},{"name":"Blood Falls","rarity":"rare","id":"blood-falls","subtitle":"Waterfall","details":"Antarctica's eerie red waterfall pours iron-rich brine from beneath Taylor Glacier, staining the ice blood-red as the iron rusts in the open air outside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blood%20Falls%20by%20Peter%20Rejcek.jpg?width=1024"},{"name":"Aletsch Glacier","rarity":"rare","id":"aletsch-glacier","subtitle":"Glacier","details":"The largest glacier in the Alps winds twenty-three kilometres through Switzerland's high peaks, a river of ice carved between jagged granite ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aletschgletscher-Eggishorn.jpg?width=1024"},{"name":"Strokkur","rarity":"rare","id":"strokkur","subtitle":"Geyser","details":"Iceland's lively geyser erupts every few minutes, shooting a bubble of near-boiling water up to thirty metres into the air beside the Great Geysir itself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Strokkur%20geyser%20eruption%2C%20close-up%20view.jpg?width=1024"},{"name":"Ross Ice Shelf","rarity":"rare","id":"ross-ice-shelf","subtitle":"Ice Shelf","details":"The world's largest ice shelf floats off Antarctica, a Texas-sized sheet of ice hundreds of metres thick that holds back glaciers across the Ross Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Earth%20-%20Ross%20Ice%20Shelf%2C%20Antarctica.jpg?width=1024"},{"name":"Tubbataha Reef","rarity":"rare","id":"tubbataha-reef","subtitle":"Reef","details":"Two remote coral atolls in the middle of the Sulu Sea protect sharks, turtles and seabirds in one of the Philippines' oldest and richest marine sanctuaries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tubbataha_Reefs_Natural_Park-112047.jpg?width=1024"},{"name":"Jeju Island","rarity":"rare","id":"jeju-island","subtitle":"Island","details":"South Korea's largest island is a shield volcano crowned by Hallasan, ringed with lava tubes, waterfalls and the tuff crater of Seongsan Ilchulbong.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seongsan_Jeju_Island_%EC%A0%9C%EC%A3%BC%EB%8F%84.jpg?width=1024"},{"name":"Komodo Island","rarity":"rare","id":"komodo-island","subtitle":"Island","details":"Dry golden hills drop to pink-tinged beaches on the home island of the Komodo dragon, the world's largest lizard, which can reach three metres long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Komodo_Island_north_aerial.jpg?width=1024"},{"name":"Faroe Islands","rarity":"rare","id":"faroe-islands","subtitle":"Archipelago","details":"Eighteen rugged North Atlantic islands of layered basalt, where grass-roofed villages sit beneath sea cliffs and waterfalls that pour straight into the ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Faroe_Islands_%28Unsplash_eRwWGWkh0vU%29.jpg?width=1024"},{"name":"Easter Island","rarity":"rare","id":"easter-island","subtitle":"Island","details":"Remote Rapa Nui, one of the most isolated inhabited islands on Earth, is ringed by volcanic craters and nearly 900 giant moai statues carved centuries ago.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Easter_Island_5.jpg?width=1024"},{"name":"Maldives","rarity":"rare","id":"maldives","subtitle":"Atoll","details":"The world's lowest, flattest nation strings 1,200 coral islands across 26 atolls in the Indian Ocean, none rising more than a few metres above the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Komandoo_%28Lhaviyani_Atoll%29.jpg?width=1024"},{"name":"Kilauea","rarity":"uncommon","id":"kilauea","subtitle":"Volcano","details":"This Hawaiian shield volcano has a summit caldera and rift zones where fluid lava fountains, lakes and flows repeatedly reshape the island's southeast shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Episode_4_of_Kilauea%27s_December_2024_eruption_2025-01-16.jpg?width=1024"},{"name":"Stromboli","rarity":"uncommon","id":"stromboli","subtitle":"Volcano","details":"This Italian island volcano rises 924 metres from the Tyrrhenian Sea, known for regular mild explosions that hurl glowing fragments above its summit crater.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_Stromboli_%28view_from_the_northeast%29.jpg?width=1024"},{"name":"Mount Agung","rarity":"uncommon","id":"mount-agung","subtitle":"Volcano","details":"Bali's highest peak is an active volcano rising 3,031 metres, a steep sacred cone whose crater and forested slopes dominate the eastern side of the island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gunung_Agung%2C_an_active_volcano_in_Bali%2C_Indonesia%3B_January_2020.jpg?width=1024"},{"name":"Mount Rinjani","rarity":"uncommon","id":"mount-rinjani","subtitle":"Volcano","details":"Indonesia's second-highest volcano rises 3,726 metres on Lombok, enclosing a deep caldera lake, Segara Anak, beside a newer cone rising from its waters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20rinjani.jpg?width=1024"},{"name":"Mount Kinabalu","rarity":"uncommon","id":"mount-kinabalu","subtitle":"Mountain","details":"Borneo's highest peak rises 4,095 metres in Malaysia, a granite massif with distinctive ridged summits, montane forests and exceptional plant diversity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kinabalu_Sabah_Borneo_Kampong_Kundasang_panorama_2.jpg?width=1024"},{"name":"Mount Semeru","rarity":"uncommon","id":"mount-semeru","subtitle":"Volcano","details":"Java's highest mountain is an active volcano rising 3,676 metres in Indonesia, sending regular ash plumes from its Jonggring Saloko summit crater.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Semeru.jpg?width=1024"},{"name":"Mount Nyiragongo","rarity":"uncommon","id":"mount-nyiragongo","subtitle":"Volcano","details":"This Congolese volcano rises 3,470 metres and is famed for its vast summit lava lake, one of the largest and most persistently active on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/An_aerial_view_of_the_towering_volcanic_peak_of_Mt._Nyiragongo.jpg?width=1024"},{"name":"Mount Cameroon","rarity":"uncommon","id":"mount-cameroon","subtitle":"Volcano","details":"West Africa's highest peak is an active volcano rising about 4,040 metres near the Gulf of Guinea, its slopes running from rainforest to alpine grassland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mt%20Cameroon%2C%20the%20active%20volcano.jpg?width=1024"},{"name":"Mount Damavand","rarity":"uncommon","id":"mount-damavand","subtitle":"Volcano","details":"Asia's highest volcano rises 5,610 metres in Iran's Alborz range, a snow-capped cone steeped in Persian mythology and topped by fumaroles near the summit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/981012-Damavand-South-IMG_9861-2.jpg?width=1024"},{"name":"Mount Kazbek","rarity":"uncommon","id":"mount-kazbek","subtitle":"Volcano","details":"This dormant Georgian volcano rises 5,047 metres in the Caucasus, a glacier-clad twin cone crowned by steep icefalls and a small chapel on a nearby ridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%93%D0%BE%D1%80%D0%B0_%D0%9A%D0%B0%D0%B7%D0%B1%D0%B5%D0%BA%2C_%D0%93%D1%80%D1%83%D0%B7%D0%B8%D1%8F.jpg?width=1024"},{"name":"Mount Triglav","rarity":"uncommon","id":"mount-triglav","subtitle":"Mountain","details":"Slovenia's highest peak rises 2,864 metres in the Julian Alps, a three-headed limestone giant that appears on the nation's coat of arms and flag emblem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Triglav.jpg?width=1024"},{"name":"Mount Teide","rarity":"uncommon","id":"mount-teide","subtitle":"Volcano","details":"Spain's highest peak is a volcano rising 3,718 metres on Tenerife, its summit cone standing inside the vast Las Canadas caldera above a sea of clouds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teide%20qtl1.jpg?width=1024"},{"name":"Pico de Orizaba","rarity":"uncommon","id":"pico-de-orizaba","subtitle":"Volcano","details":"Mexico's highest peak is a dormant volcano rising 5,636 metres, its glacier-capped cone also known by its Nahuatl name, Citlaltepetl, meaning star mountain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pico_de_Orizaba_desde_Hidalgo%2C_Puebla.jpg?width=1024"},{"name":"Popocatepetl","rarity":"uncommon","id":"popocatepetl","subtitle":"Volcano","details":"This active Mexican volcano rises 5,393 metres near Puebla, its name meaning smoking hill in Nahuatl, with a broad crater that regularly emits ash and gas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mexico-Popocatepetl.jpg?width=1024"},{"name":"Mount Saint Helens","rarity":"uncommon","id":"mount-saint-helens","subtitle":"Volcano","details":"This Washington volcano is famed for its massive 1980 eruption, which removed its summit, formed a horseshoe crater and flattened forests for miles around.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MSH82_st_helens_plume_from_harrys_ridge_05-19-82.jpg?width=1024"},{"name":"Mauna Kea","rarity":"uncommon","id":"mauna-kea","subtitle":"Volcano","details":"Measured from its base on the ocean floor, this Hawaiian volcano is Earth's tallest mountain, rising 4,207 metres above the sea into exceptionally clear skies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mauna_Kea_from_the_ocean.jpg?width=1024"},{"name":"Mount Meru","rarity":"uncommon","id":"mount-meru","subtitle":"Volcano","details":"This Tanzanian volcano rises 4,562 metres inside Arusha National Park, with a horseshoe caldera, ash cone and views toward nearby Mount Kilimanjaro.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_meru_with_snow%2C_Arusha_Region%2C_Tanzania.jpg?width=1024"},{"name":"Mount Elgon","rarity":"uncommon","id":"mount-elgon","subtitle":"Volcano","details":"This extinct shield volcano on the Uganda-Kenya border rises 4,321 metres and holds one of the world's largest intact calderas, about 40 kilometres wide in all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Elgon-Wagagai.jpg?width=800"},{"name":"Helmcken Falls","rarity":"uncommon","id":"helmcken-falls","subtitle":"Waterfall","details":"The Murtle River drops 141 metres over a lava cliff into a mist-filled amphitheatre, and spray can freeze into a huge ice cone at its base in winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Helmcken_Falls_Soft_%28189128621%29.jpeg?width=1024"},{"name":"Takakkaw Falls","rarity":"uncommon","id":"takakkaw-falls","subtitle":"Waterfall","details":"Meltwater from the Daly Glacier plunges about 373 metres in the Yoho Valley, with a main free leap of 254 metres that roars at peak summer melt.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Takakkaw_Falls_-_panoramio_%281%29.jpg?width=1024"},{"name":"Shoshone Falls","rarity":"uncommon","id":"shoshone-falls","subtitle":"Waterfall","details":"The Snake River drops 65 metres over a horseshoe rim about 300 metres wide, a fall slightly higher than Niagara in the high desert of southern Idaho.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shoshone_Falls%2C_Idaho.jpg?width=1024"},{"name":"Montmorency Falls","rarity":"uncommon","id":"montmorency-falls","subtitle":"Waterfall","details":"The Montmorency River plunges 83 metres over a cliff into the St. Lawrence, a drop about 30 metres higher than Niagara, spanned by a suspension bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Montmorency_Falls_01.jpg?width=1024"},{"name":"Dudhsagar Falls","rarity":"uncommon","id":"dudhsagar-falls","subtitle":"Waterfall","details":"The Mandovi River falls about 310 metres in four tiers through lush forest, its white foam inspiring a name that means sea of milk in local language.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Doodhsagar_Fall.jpg?width=800"},{"name":"Nohkalikai Falls","rarity":"uncommon","id":"nohkalikai-falls","subtitle":"Waterfall","details":"Rainwater collected on a high plateau plunges 340 metres in a single leap, the tallest plunge waterfall in India, into a strikingly green pool below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NohKaLikai_Falls_V2_Wiki.jpg?width=1024"},{"name":"Wallaman Falls","rarity":"uncommon","id":"wallaman-falls","subtitle":"Waterfall","details":"Stony Creek drops about 268 metres in a single main leap into a gorge in the Wet Tropics, making this Australia's tallest permanent single-drop fall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wallaman_Falls.jpg?width=1024"},{"name":"Taughannock Falls","rarity":"uncommon","id":"taughannock-falls","subtitle":"Waterfall","details":"Taughannock Creek plunges 66 metres between cliffs up to 120 metres high, a single drop taller than Niagara in a glacially carved Finger Lakes gorge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taughannock_Falls%2C_Ulysses%2C_NY_-_2024.jpg?width=800"},{"name":"Augrabies Falls","rarity":"uncommon","id":"augrabies-falls","subtitle":"Waterfall","details":"The Orange River pours into an 18-kilometre granite gorge, dropping about 56 metres at the main fall where the roar carries across the arid landscape.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Augrabies_Falls%2C_March_2008.jpg?width=1024"},{"name":"Kalambo Falls","rarity":"uncommon","id":"kalambo-falls","subtitle":"Waterfall","details":"The Kalambo River makes a single uninterrupted drop of about 235 metres into the Lake Tanganyika rift, one of Africa's tallest unbroken waterfalls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kalambo_Falls.jpg?width=1024"},{"name":"Sutherland Falls","rarity":"uncommon","id":"sutherland-falls","subtitle":"Waterfall","details":"Water from Lake Quill spills about 580 metres in three great leaps down a glaciated valley wall, ranking among the tallest waterfalls in New Zealand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sutherland_Falls_2011.jpg?width=800"},{"name":"Veliki Slap","rarity":"uncommon","id":"veliki-slap","subtitle":"Waterfall","details":"The Korana River begins at this 78-metre fall, the tallest in its lake district, where water fans over a tufa barrier between the upper and lower lakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Big%20Waterfall%20%28Veliki%20Slap%29%20in%20Plitvice%20Lakes%20National%20Park%2C%20Croatia%20%2848607655996%29.jpg?width=1024"},{"name":"Murchison Falls","rarity":"uncommon","id":"murchison-falls","subtitle":"Waterfall","details":"The White Nile squeezes through a gap only about seven metres wide and plunges 43 metres, turning a calm river into a violent, foaming torrent below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Murchison_Twin_Falls%2C_Uganda_%2816093084916%29.jpg?width=1024"},{"name":"Ruacana Falls","rarity":"uncommon","id":"ruacana-falls","subtitle":"Waterfall","details":"The Kunene River drops about 120 metres over a basalt escarpment about 700 metres wide, in a series of cascades along a remote, rocky border valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ruacana_Falls_at_High_Water_from_distance_in_03-2011_by_Tom_Jakobi.JPG?width=1024"},{"name":"Black Canyon of the Gunnison","rarity":"uncommon","id":"black-canyon-of-the-gunnison","subtitle":"Canyon","details":"Colorado's Gunnison River carved an exceptionally steep, narrow canyon where dark, lichen-streaked walls plunge over 2,700 feet with little sunlight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20Canyon%20of%20the%20Gunnison%2003.jpg?width=1024"},{"name":"Glen Canyon","rarity":"uncommon","id":"glen-canyon","subtitle":"Canyon","details":"The Colorado River winds through Glen Canyon's smooth red sandstone in Arizona and Utah, a labyrinth of side canyons, arches and sculpted rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colorado%20River%20downstream%20of%20Glen%20Canyon%20Dam%2C%20Page%2C%20Arizona%20-%20April%202026.jpg?width=1024"},{"name":"Samaria Gorge","rarity":"uncommon","id":"samaria-gorge","subtitle":"Gorge","details":"Crete's Samaria Gorge runs 10 miles to the Libyan Sea, narrowing at the Iron Gates to a passage just a few feet wide between towering cliffs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Samaria%20Gorge%2C%20Crete%20%28150857%29%20%289450576425%29.jpg?width=1024"},{"name":"Vikos Gorge","rarity":"uncommon","id":"vikos-gorge","subtitle":"Gorge","details":"Greece's Vikos Gorge is among the deepest in the world relative to its width, its limestone walls sheltering rare herbs, eagles and the Voidomatis springs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vikos%20Gorge%20seen%20from%20Vikos%20Gorge%20View%20Point%2C%20September%202022%2001.jpg?width=1024"},{"name":"Todra Gorge","rarity":"uncommon","id":"todra-gorge","subtitle":"Gorge","details":"Morocco's Todra Gorge narrows to a flat corridor between sheer limestone walls 1,300 feet high, glowing orange in the morning and evening light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Todra%20Gorge.jpg?width=1024"},{"name":"Fjadrargljufur Canyon","rarity":"uncommon","id":"fjadrargljufur","subtitle":"Canyon","details":"Iceland's feather canyon winds for over a mile in serpentine curves, its moss-covered walls carved by glacial meltwater at the end of the last ice age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fja%C3%B0r%C3%A1rglj%C3%BAfur%2001.jpg?width=1024"},{"name":"Studlagil Canyon","rarity":"uncommon","id":"studlagil-canyon","subtitle":"Canyon","details":"Iceland's Studlagil Canyon lines a glacial river with towering hexagonal basalt columns, revealed only after a dam project lowered the water level.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stu%C3%B0lagil%20Canyon%201.jpg?width=1024"},{"name":"Kalahari Desert","rarity":"uncommon","id":"kalahari-desert","subtitle":"Desert","details":"The Kalahari is a vast semi-arid savanna of red sand across southern Africa, home to meerkats, black-maned lions and ancient San hunter-gatherer cultures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sand%20dune%20in%20the%20Kalahari%20Desert%20%28Namibia%29.jpg?width=1024"},{"name":"Mojave Desert","rarity":"uncommon","id":"mojave-desert","subtitle":"Desert","details":"North America's driest desert spreads across four states, defined by twisted Joshua trees, volcanic cinder cones and some of the hottest places on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mojave%20Desert%20%28211034223%29.jpeg?width=1024"},{"name":"Thar Desert","rarity":"uncommon","id":"thar-desert","subtitle":"Desert","details":"The Great Indian Desert covers much of Rajasthan, a densely peopled land of rolling dunes, camel caravans and fortified cities like golden Jaisalmer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thar%20Desert%2005.jpg?width=1024"},{"name":"White Sands","rarity":"uncommon","id":"white-sands","subtitle":"Dunes","details":"New Mexico's White Sands is the world's largest gypsum dunefield, 275 square miles of brilliant white waves that shift constantly with the desert wind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White%20Sands%20National%20Monument%20-%20image%20of%20a%20dune.jpg?width=1024"},{"name":"Great Sand Dunes","rarity":"uncommon","id":"great-sand-dunes","subtitle":"Dunes","details":"North America's tallest dunes rise 750 feet against Colorado's Sangre de Cristo Mountains, built by sand trapped from a vast valley floor by the winds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Sand%20Dunes%2003.jpg?width=1024"},{"name":"Erg Chebbi","rarity":"uncommon","id":"erg-chebbi","subtitle":"Dunes","details":"Morocco's Erg Chebbi is a sea of Saharan sand whose great dunes rise nearly 500 feet and shift in colour from gold to deep rose at sunset.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Erg%20Chebbi%20in%20the%20evening%20light.jpg?width=1024"},{"name":"Lençóis Maranhenses","rarity":"uncommon","id":"lencois-maranhenses","subtitle":"Dunes","details":"Brazil's Lençóis Maranhenses fills each rainy season with crystal lagoons between white quartz dunes, where fish appear in pools cut off from any river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lagoon%20in%20sanddunes%2C%20Len%C3%A7%C3%B3is%20Maranhenses.jpg?width=1024"},{"name":"Painted Desert","rarity":"uncommon","id":"painted-desert","subtitle":"Desert","details":"Arizona's Painted Desert glows in bands of red, pink, lavender and grey, its coloured badlands formed from ancient floodplain muds and volcanic ash.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colorful%20Painted%20Desert.jpg?width=1024"},{"name":"Badlands","rarity":"uncommon","id":"badlands","subtitle":"Badlands","details":"South Dakota's Badlands are a maze of sharply eroded buttes, pinnacles and spires rich in fossils of ancient rhinos, horses and saber-toothed cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Badlands%20National%20Park%2C%20South%20Dakota%202014%2010.jpg?width=1024"},{"name":"Ganges River","rarity":"uncommon","id":"ganges-river","subtitle":"River","details":"Sacred to Hindus and central to life for hundreds of millions, the Ganges flows about 2,525 kilometres from the Himalayas to the Bay of Bengal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boats%20at%20sunrise%20Ganges%20River%20Varanasi%20Uttar%20Pradesh%20Schwiki.jpg?width=1024"},{"name":"Volga River","rarity":"uncommon","id":"volga-river","subtitle":"River","details":"At about 3,530 kilometres the Volga is Europe's longest river, flowing through central Russia to the Caspian Sea and long central to its culture.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Volga%20river%20P6190247%202600.jpg?width=1024"},{"name":"Lake Tahoe","rarity":"uncommon","id":"lake-tahoe","subtitle":"Lake","details":"A deep, strikingly clear alpine lake on the California-Nevada border, Tahoe is North America's largest alpine lake and rarely freezes over.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Tahoe%20at%20morning%20-%207-2023.jpg?width=1024"},{"name":"Crater Lake","rarity":"uncommon","id":"crater-lake","subtitle":"Lake","details":"Oregon's Crater Lake fills the collapsed caldera of Mount Mazama; with no inlets, its exceptionally clear water is among the deepest in America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crater%20Lake%20July%202024-4.jpg?width=1024"},{"name":"Lake Atitlán","rarity":"uncommon","id":"lake-atitlan","subtitle":"Lake","details":"Ringed by volcanoes in Guatemala's highlands, deep blue Lake Atitlán fills a huge volcanic caldera formed by an eruption about 84,000 years ago.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Atitlan%20at%20sunrise.jpg?width=1024"},{"name":"Lake Louise","rarity":"uncommon","id":"lake-louise","subtitle":"Lake","details":"This glacial lake in Banff National Park is famed for emerald water, the Victoria Glacier behind it and the grand Fairmont Chateau on its shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banff%20National%20Park%20%28AB%2C%20Canada%29%2C%20Lake%20Louise%20--%202022%20--%202197.jpg?width=1024"},{"name":"Loch Ness","rarity":"uncommon","id":"loch-ness","subtitle":"Lake","details":"Scotland's most famous loch holds more fresh water than all the lakes of England and Wales combined, and is home to the enduring Nessie legend.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View-of-Loch-Ness-Scotland.jpg?width=1024"},{"name":"Thames River","rarity":"uncommon","id":"thames-river","subtitle":"River","details":"England's best-known river flows 346 kilometres from the Cotswolds through Oxford and London, widening into an estuary that meets the North Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20River%20Thames%2C%20Moulsford%20-%20geograph.org.uk%20-%20695707.jpg?width=1024"},{"name":"Seine River","rarity":"uncommon","id":"seine-river","subtitle":"River","details":"The Seine flows about 777 kilometres through Paris and Normandy to the English Channel at Le Havre, joined in the capital by dozens of bridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20across%20the%20Seine%20at%20Caudebec-en-Caux%2C%20Normandy%2C%20France%20-%20panoramio.jpg?width=1024"},{"name":"Bay of Fundy","rarity":"uncommon","id":"bay-of-fundy","subtitle":"Bay","details":"Between Nova Scotia and New Brunswick, Fundy has the highest tides on Earth, rising as much as 16 metres and exposing vast ocean floors twice daily.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hopewell%20Rocks%20New%20Brunswick%20Canada%20Bay%20of%20Fundy%20%2838346951175%29.jpg?width=1024"},{"name":"Milford Sound","rarity":"uncommon","id":"milford-sound","subtitle":"Fjord","details":"Carved by glaciers in New Zealand's Fiordland, this steep fjord is crowned by Mitre Peak, which rises more than 1,600 metres straight from the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milford%20Sound%20in%20Fiordland%20National%20Park%2001.jpg?width=1024"},{"name":"Geirangerfjord","rarity":"uncommon","id":"geirangerfjord","subtitle":"Fjord","details":"A branch of Norway's Storfjorden, this UNESCO-listed fjord is flanked by abandoned hillside farms, snowcapped peaks and near-vertical rock walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Geirangerfjord%20LC0188.jpg?width=800"},{"name":"Lake Michigan","rarity":"uncommon","id":"lake-michigan","subtitle":"Lake","details":"The only Great Lake lying entirely within the United States, Michigan is ringed by giant sand dunes, lighthouses and the city of Chicago.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Michigan%2C%20near%20Sleeping%20Bear%20dunes%20%2820903362288%29.jpg?width=1024"},{"name":"Yellow River","rarity":"uncommon","id":"yellow-river","subtitle":"River","details":"China's second-longest river is named for the yellow silt it carries from the Loess Plateau, and its valley was a cradle of early Chinese civilisation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Yellow%20River%20at%20Lanzhou%20-%20%E5%85%B0%E5%B7%9E%E9%BB%84%E6%B2%B3%E8%BE%B9%E4%B8%8A%20%2817331114205%29.jpg?width=1024"},{"name":"Euphrates River","rarity":"uncommon","id":"euphrates-river","subtitle":"River","details":"The western of Mesopotamia's twin great rivers, the Euphrates flows about 2,800 kilometres from Turkey through Syria and Iraq to the Persian Gulf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Euphrates%20River-Iraq.jpg?width=1024"},{"name":"Irrawaddy River","rarity":"uncommon","id":"irrawaddy-river","subtitle":"River","details":"Myanmar's principal river flows about 2,170 kilometres from Himalayan-fed headwaters in the north, past Bagan and Mandalay, to the Andaman Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20160801%20Irrawaddy%20River%20Bagan%206788.jpg?width=1024"},{"name":"Cenote Ik Kil","rarity":"uncommon","id":"cenote-ik-kil","subtitle":"Cenote","details":"Mexico's Cenote Ik Kil is a round, open sinkhole near Chichen Itza, where vines hang to clear jade water 26 metres below the jungle floor above it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cenote_Ik_Kil%2C_Yucatan%2C_Dec_2011_-_06.jpg?width=1024"},{"name":"Blue Grotto","rarity":"uncommon","id":"blue-grotto","subtitle":"Grotto","details":"Capri's Blue Grotto is a sea cave where sunlight passing through deep water turns the whole cavern an intense, glowing electric blue at midday.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue_Grotto_Capri_Inside.jpg?width=1024"},{"name":"Cango Caves","rarity":"uncommon","id":"cango-caves","subtitle":"Cave","details":"South Africa's Cango Caves wind through limestone near Oudtshoorn, opening into vast halls of dripstone columns, towers and flowstone curtains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cango_caves_04.jpg?width=1024"},{"name":"Jenolan Caves","rarity":"uncommon","id":"jenolan-caves","subtitle":"Cave","details":"Australia's Jenolan Caves in the Blue Mountains are among the oldest open caves known, laced with pure limestone formations and underground rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Inside_Jenolan_caves.jpg?width=1024"},{"name":"Batu Caves","rarity":"uncommon","id":"batu-caves","subtitle":"Cave","details":"Malaysia's Batu Caves rise inside a limestone hill over 400 million years old, its vast Temple Cave reached by 272 brightly painted concrete steps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Batu_Caves_interior.jpg?width=1024"},{"name":"Deer Cave","rarity":"uncommon","id":"deer-cave","subtitle":"Cave","details":"Borneo's Deer Cave in Mulu National Park holds one of the largest cave passages on Earth and a nightly exodus of millions of wrinkle-lipped bats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Deer_Cave_entry%2C_Sarawak%2C_April_2025_01.jpg?width=1024"},{"name":"Wind Cave","rarity":"uncommon","id":"wind-cave","subtitle":"Cave","details":"South Dakota's Wind Cave is famous for boxwork, rare honeycomb blades of calcite projecting from its walls, found in few other caves in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cave_Boxwork-Wind_Cave.JPG?width=1024"},{"name":"Lechuguilla Cave","rarity":"uncommon","id":"lechuguilla-cave","subtitle":"Cave","details":"New Mexico's Lechuguilla Cave dazzles with rare gypsum chandeliers, cave pearls and soda straws in passages kept pristine and closed to the public.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lechuguilla_Cave_Pearlsian_Gulf.jpg?width=800"},{"name":"Cave of Swallows","rarity":"uncommon","id":"cave-of-swallows","subtitle":"Cave","details":"Mexico's Cave of Swallows is a vast open pit 333 metres deep, so wide that flocks of swifts and parakeets spiral up from its floor at dawn each day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golondrinas_top2.jpg?width=1024"},{"name":"Xiaozhai Tiankeng","rarity":"uncommon","id":"xiaozhai-tiankeng","subtitle":"Sinkhole","details":"China's Xiaozhai Tiankeng is the world's deepest sinkhole, plunging 662 metres with sheer walls, a forest and an underground river hidden at its base.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Xiaozhaitiankeng.jpg?width=1024"},{"name":"Kazumura Cave","rarity":"uncommon","id":"kazumura-cave","subtitle":"Lava Tube","details":"Hawaii's Kazumura Cave is the world's longest lava tube, running 65 kilometres down Kilauea's flank with smooth, ropy walls frozen mid-flow forever.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kazumura_collapsed_floor.jpg?width=800"}]});
